const raw = items[0].json;
const alert = raw.body || raw;

const ip = alert.agent?.ip 
  || alert.data?.srcip 
  || null;

const hash = alert.data?.file?.sha256 
  || alert.syscheck?.sha256_after 
  || null;

const rule = alert.rule?.description || 'Unknown Rule';
const ruleId = alert.rule?.id || 'N/A';
const ruleLevel = alert.rule?.level || 0;
const agentName = alert.agent?.name || 'Unknown Agent';
const timestamp = alert.timestamp || new Date().toISOString();

return [{
  json: {
    ip,
    hash,
    rule,
    ruleId,
    ruleLevel,
    agentName,
    timestamp,
    hasHash: hash !== null && hash !== '',
    hasIp: ip !== null && ip !== '',
    raw: alert
  }
}];

