const data = items[0].json;

const maliciousScore = 
  data?.data?.attributes?.last_analysis_stats?.malicious ?? 0;

const ruleLevel = data?.ruleLevel || 
  $node["Extract IOC"].json["ruleLevel"] || 0;

// Flag as suspicious if VT score > 0 OR rule level is critical
const isSuspicious = maliciousScore > 0 || ruleLevel >= 10;

return [{
  json: {
    ...data,
    maliciousScore: maliciousScore,
    ruleLevel: ruleLevel,
    isSuspicious: isSuspicious,
    detectionMethod: maliciousScore > 0 ? 'VirusTotal' : 
                     ruleLevel >= 10 ? 'Wazuh Rule Level' : 'None'
  }
}];
